// WOOLRICH | PREPARAR SOLO LOS DATOS NECESARIOS PARA EL KANBAN

const row = $json;

function hasValue(value) {
  return value !== undefined && value !== null && String(value).trim() !== '';
}

function pick(...keys) {
  for (const key of keys) {
    if (hasValue(row[key])) return row[key];
  }
  return null;
}

function text(value) {
  if (!hasValue(value)) return null;
  return String(value).trim();
}

function digits(value) {
  const valueText = text(value);
  return valueText ? valueText.replace(/\D/g, '') : null;
}

function normalize(value) {
  return String(value ?? '')
    .trim()
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[_-]+/g, ' ')
    .replace(/\s+/g, ' ');
}

function excelSerialToIso(serial) {
  const milliseconds = Math.round((serial - 25569) * 86400 * 1000);
  return new Date(milliseconds).toISOString();
}

function sheetDateToIso(value) {
  if (!hasValue(value)) return null;

  if (typeof value === 'number') {
    if (value > 20000 && value < 100000) {
      return excelSerialToIso(value);
    }

    const parsedNumberDate = new Date(value);
    if (!Number.isNaN(parsedNumberDate.getTime())) {
      return parsedNumberDate.toISOString();
    }
  }

  const raw = String(value).trim();

  if (/^\d+(?:\.\d+)?$/.test(raw)) {
    const numeric = Number(raw);

    if (numeric > 20000 && numeric < 100000) {
      return excelSerialToIso(numeric);
    }
  }

  const spanishDate = raw.match(
    /^(\d{1,2})[/-](\d{1,2})[/-](\d{4})(?:[,\s]+(\d{1,2}):(\d{2})(?::(\d{2}))?\s*(a\.?\s*m\.?|p\.?\s*m\.?)?)?$/i
  );

  if (spanishDate) {
    let [, day, month, year, hour = '0', minute = '0', second = '0', meridiem = ''] = spanishDate;
    let parsedHour = Number(hour);

    const normalizedMeridiem = normalize(meridiem).replace(/\s/g, '');

    if (normalizedMeridiem.startsWith('p') && parsedHour < 12) parsedHour += 12;
    if (normalizedMeridiem.startsWith('a') && parsedHour === 12) parsedHour = 0;

    const isoWithMexicoOffset =
      `${year}-${String(month).padStart(2, '0')}-${String(day).padStart(2, '0')}` +
      `T${String(parsedHour).padStart(2, '0')}:${String(minute).padStart(2, '0')}` +
      `:${String(second).padStart(2, '0')}-06:00`;

    const parsed = new Date(isoWithMexicoOffset);
    return Number.isNaN(parsed.getTime()) ? null : parsed.toISOString();
  }

  const parsed = new Date(raw);
  return Number.isNaN(parsed.getTime()) ? null : parsed.toISOString();
}

function resolveStage(sheetStage, appointmentStatus, lastClientMessage) {
  const aliases = {
    'contacto nuevo': 'contactos_nuevos',
    'contactos nuevos': 'contactos_nuevos',
    'contactos nuevo': 'contactos_nuevos',
    'contactos_nuevos': 'contactos_nuevos',
    'nuevo': 'contactos_nuevos',

    'pregunto por fechas': 'preguntaron_fechas',
    'preguntaron por fechas': 'preguntaron_fechas',
    'preguntaron fechas': 'preguntaron_fechas',
    'preguntaron_fechas': 'preguntaron_fechas',
    'fechas': 'preguntaron_fechas',

    'cita agendada': 'cita_agendada',
    'cita confirmada': 'cita_agendada',
    'cita_agendada': 'cita_agendada',

    'asistio a consulta': 'asistio_consulta',
    'asistio consulta': 'asistio_consulta',
    'asistio_consulta': 'asistio_consulta',

    'cirugia agendada': 'cirugia_agendada',
    'cirugia_agendada': 'cirugia_agendada',

    'cita cancelada': 'cita_cancelada',
    'cancelada': 'cita_cancelada',
    'cita_cancelada': 'cita_cancelada'
  };

  const stageFromSheet = aliases[normalize(sheetStage)];
  if (stageFromSheet) return stageFromSheet;

  const normalizedStatus = normalize(appointmentStatus);
  if (
    normalizedStatus.includes('cita confirmada') ||
    normalizedStatus.includes('cita actualizada')
  ) {
    return 'cita_agendada';
  }

  const normalizedMessage = normalize(lastClientMessage);
  if (
    /\b(fecha|fechas|dia|dias|horario|horarios|hora|disponibilidad|manana|tarde|noche)\b/.test(
      normalizedMessage
    )
  ) {
    return 'preguntaron_fechas';
  }

  return 'contactos_nuevos';
}

const subscriberIdRaw = pick('subscriber_id', 'Subscriber ID');
const subscriberId = Number(subscriberIdRaw);

if (!Number.isFinite(subscriberId)) {
  throw new Error('La fila no tiene un subscriber_id válido.');
}

const lastActivityRaw = pick('last_activity_timestamp');
const lastActivityTimestamp = hasValue(lastActivityRaw)
  ? Number(lastActivityRaw)
  : null;

const statusCita = text(pick('Status cita', 'status_cita'));
const lastClientMessage = text(
  pick('ultimo_mensaje_cli', 'ultimo_mensaje_cliente')
);
const sheetStage = text(pick('etapa', 'Etapa'));

return [
  {
    json: {
      p_company_key: 'dr-woolrich',
      p_subscriber_id: subscriberId,
      p_whatsapp_phone: digits(pick('whatsapp_phone', 'Telefono', 'Teléfono')),
      p_nombre_paciente: text(
        pick('Nombre del paciente', 'nombre_paciente', 'Nombre')
      ),
      p_fecha_cita: sheetDateToIso(
        pick('Fecha de la cita', 'fecha_cita')
      ),
      p_status_cita: statusCita,
      p_last_activity_timestamp:
        Number.isFinite(lastActivityTimestamp) ? lastActivityTimestamp : null,
      p_last_activity_at:
        Number.isFinite(lastActivityTimestamp) && lastActivityTimestamp > 0
          ? new Date(lastActivityTimestamp * 1000).toISOString()
          : null,
      p_ultimo_mensaje_cliente: lastClientMessage,
      p_kanban_stage: resolveStage(
        sheetStage,
        statusCita,
        lastClientMessage
      )
    }
  }
];
